/**
 * Chart Preparation Countdown Helper for Indian Railways (IRCTC)
 * 
 * IRCTC Chart Preparation Rules:
 * 1. Day & Evening Trains (departing 08:01 to 23:59):
 *    First chart is prepared 4 hours before scheduled departure.
 * 2. Early Morning Trains (departing 00:01 to 08:00):
 *    First chart is prepared on the previous evening at 20:00 (8:00 PM).
 * 3. Second Chart:
 *    Prepared 30 minutes before train departure.
 */

export interface ChartPreparationInfo {
  isPrepared: boolean;
  isInProgress: boolean;
  isDeparted: boolean;
  targetChartDate: Date | null;
  departureDate: Date | null;
  remainingMs: number;
  remainingHours: number;
  remainingMinutes: number;
  remainingSeconds: number;
  formattedTargetTime: string;
  formattedDepartureTime: string;
  headlineText: string;
  subText: string;
}

const MONTH_NAMES: Record<string, number> = {
  jan: 0, feb: 1, mar: 2, apr: 3, may: 4, jun: 5,
  jul: 6, aug: 7, sep: 8, oct: 9, nov: 10, dec: 11
};

/**
 * Parses a variety of journey dates and departure time strings into a valid JS Date.
 */
export function parseJourneyDepartureDateTime(
  journeyDateStr: string,
  departureTimeStr?: string
): Date | null {
  if (!journeyDateStr) return null;

  let hours = 21;
  let minutes = 20;

  if (departureTimeStr) {
    const timeMatch = departureTimeStr.match(/(\d{1,2}):(\d{2})(?:\s*([APap][Mm]))?/);
    if (timeMatch) {
      let h = parseInt(timeMatch[1], 10);
      const m = parseInt(timeMatch[2], 10);
      const meridiem = timeMatch[3]?.toUpperCase();
      if (meridiem === 'PM' && h < 12) h += 12;
      if (meridiem === 'AM' && h === 12) h = 0;
      hours = h;
      minutes = m;
    }
  }

  const clean = journeyDateStr.trim();

  // Pattern 1: Named month (e.g. "9 Oct 2026", "09 Oct 2026", "9-Oct-2026")
  const namedMatch = clean.match(/(\d{1,2})[\s\-]+([A-Za-z]{3,})[\s\-]+(\d{4})/);
  if (namedMatch) {
    const d = parseInt(namedMatch[1], 10);
    const mStr = namedMatch[2].slice(0, 3).toLowerCase();
    const y = parseInt(namedMatch[3], 10);
    if (MONTH_NAMES[mStr] !== undefined) {
      const dt = new Date(y, MONTH_NAMES[mStr], d, hours, minutes, 0);
      if (!isNaN(dt.getTime())) return dt;
    }
  }

  // Pattern 2: YYYY-MM-DD
  if (/^\d{4}[\-\/]\d{1,2}[\-\/]\d{1,2}/.test(clean)) {
    const parts = clean.split(/[\-\/]/);
    const y = parseInt(parts[0], 10);
    const m = parseInt(parts[1], 10) - 1;
    const d = parseInt(parts[2], 10);
    const dt = new Date(y, m, d, hours, minutes, 0);
    if (!isNaN(dt.getTime())) return dt;
  }

  // Pattern 3: DD-MM-YYYY or DD/MM/YYYY
  if (/^\d{1,2}[\-\/]\d{1,2}[\-\/]\d{4}/.test(clean)) {
    const parts = clean.split(/[\-\/]/);
    const d = parseInt(parts[0], 10);
    const m = parseInt(parts[1], 10) - 1;
    const y = parseInt(parts[2], 10);
    const dt = new Date(y, m, d, hours, minutes, 0);
    if (!isNaN(dt.getTime())) return dt;
  }

  // Fallback direct parse
  const fallback = new Date(clean);
  if (!isNaN(fallback.getTime())) {
    fallback.setHours(hours, minutes, 0, 0);
    return fallback;
  }

  return null;
}

/**
 * Calculates official IRCTC expected chart preparation time based on train departure.
 */
export function getExpectedChartTime(departureDate: Date): Date {
  const depHours = departureDate.getHours();

  // IRCTC Rule: Early morning trains (00:01 to 08:00 AM) prepare chart at 20:00 (8:00 PM) previous day
  if (depHours >= 0 && depHours < 8) {
    const chartDate = new Date(departureDate);
    chartDate.setDate(chartDate.getDate() - 1);
    chartDate.setHours(20, 0, 0, 0);
    return chartDate;
  }

  // Day & Evening trains: 4 hours prior to departure
  return new Date(departureDate.getTime() - 4 * 60 * 60 * 1000);
}

/**
 * Format a Date to "5:20 PM" or "5:20 PM, 9 Oct"
 */
export function formatTimeWithAmPm(date: Date, includeDate: boolean = false): string {
  let hours = date.getHours();
  const minutes = date.getMinutes();
  const ampm = hours >= 12 ? 'PM' : 'AM';
  hours = hours % 12;
  hours = hours ? hours : 12; // '0' should be 12
  const minStr = minutes < 10 ? `0${minutes}` : `${minutes}`;
  const timeStr = `${hours}:${minStr} ${ampm}`;

  if (!includeDate) return timeStr;

  const day = date.getDate();
  const monthShort = date.toLocaleString('en-US', { month: 'short' });
  return `${timeStr}, ${day} ${monthShort}`;
}

/**
 * Complete status calculator comparing current time against departure and charting rules.
 */
export function calculateChartPreparationStatus(
  journeyDateStr: string,
  departureTimeStr?: string,
  isChartPreparedProp: boolean = false,
  currentTime: Date = new Date()
): ChartPreparationInfo {
  if (isChartPreparedProp) {
    return {
      isPrepared: true,
      isInProgress: false,
      isDeparted: false,
      targetChartDate: null,
      departureDate: null,
      remainingMs: 0,
      remainingHours: 0,
      remainingMinutes: 0,
      remainingSeconds: 0,
      formattedTargetTime: '',
      formattedDepartureTime: '',
      headlineText: 'Chart Prepared',
      subText: 'Final coach and berth allocations have been finalized by IRCTC.'
    };
  }

  const departureDate = parseJourneyDepartureDateTime(journeyDateStr, departureTimeStr);
  if (!departureDate) {
    return {
      isPrepared: false,
      isInProgress: false,
      isDeparted: false,
      targetChartDate: null,
      departureDate: null,
      remainingMs: 0,
      remainingHours: 0,
      remainingMinutes: 0,
      remainingSeconds: 0,
      formattedTargetTime: '4 hours prior to departure',
      formattedDepartureTime: departureTimeStr || '',
      headlineText: 'First Chart Expected ~4 hrs prior',
      subText: 'IRCTC prepares first charts 4 hours before scheduled departure.'
    };
  }

  const targetChartDate = getExpectedChartTime(departureDate);
  const nowMs = currentTime.getTime();
  const chartMs = targetChartDate.getTime();
  const depMs = departureDate.getTime();

  // If train has already departed
  if (nowMs >= depMs) {
    return {
      isPrepared: false,
      isInProgress: false,
      isDeparted: true,
      targetChartDate,
      departureDate,
      remainingMs: 0,
      remainingHours: 0,
      remainingMinutes: 0,
      remainingSeconds: 0,
      formattedTargetTime: formatTimeWithAmPm(targetChartDate, true),
      formattedDepartureTime: formatTimeWithAmPm(departureDate, true),
      headlineText: 'Train Departed',
      subText: 'Scheduled departure has passed.'
    };
  }

  // If we are past the 4-hour mark but IRCTC hasn't published 'Prepared' yet
  if (nowMs >= chartMs && nowMs < depMs) {
    return {
      isPrepared: false,
      isInProgress: true,
      isDeparted: false,
      targetChartDate,
      departureDate,
      remainingMs: 0,
      remainingHours: 0,
      remainingMinutes: 0,
      remainingSeconds: 0,
      formattedTargetTime: formatTimeWithAmPm(targetChartDate, false),
      formattedDepartureTime: formatTimeWithAmPm(departureDate, false),
      headlineText: 'Chart Preparation In Progress',
      subText: 'IRCTC is currently finalizing berth allotments. Status will update any moment.'
    };
  }

  // Chart preparation is in the future
  const diffMs = chartMs - nowMs;
  const totalSeconds = Math.floor(diffMs / 1000);
  const hours = Math.floor(totalSeconds / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;

  const sameDay = targetChartDate.toDateString() === currentTime.toDateString();
  const formattedTargetTime = formatTimeWithAmPm(targetChartDate, !sameDay);
  const formattedDepartureTime = formatTimeWithAmPm(departureDate, !sameDay);

  let headlineText = '';
  if (hours > 24) {
    const days = Math.floor(hours / 24);
    headlineText = `First Chart in ~${days}d ${hours % 24}h`;
  } else if (hours > 0) {
    headlineText = `First Chart in ~${hours}h ${minutes}m`;
  } else {
    headlineText = `First Chart in ~${minutes}m ${seconds}s`;
  }

  return {
    isPrepared: false,
    isInProgress: false,
    isDeparted: false,
    targetChartDate,
    departureDate,
    remainingMs: diffMs,
    remainingHours: hours,
    remainingMinutes: minutes,
    remainingSeconds: seconds,
    formattedTargetTime,
    formattedDepartureTime,
    headlineText,
    subText: `Expected around ${formattedTargetTime} · 4 hours before train departure`
  };
}
